import { STATUS_COLORS } from "../data/odontogramaConstants";
import { getWholeAction } from "../utils/odontogramaHelpers";

/*
 * Siluetas de cada pieza en vista vestibular, dibujadas con proporciones anatómicas reales
 * (Wheeler's Dental Anatomy): corona arriba, raíz abajo y mesial hacia la derecha.
 * Solo se guardan el lado derecho del paciente (11-18 y 41-48); el lado izquierdo
 * (21-28 y 31-38) es el mismo dibujo en espejo.
 *  - Superiores: incisivo central ancho (8.5 mm) y lateral más angosto; canino con la raíz
 *    más larga; 1.er premolar con 2 raíces; molares con 3 raíces (MV, palatina y DV).
 *  - Inferiores: incisivo central el más angosto (5 mm); premolares de 1 raíz; molares con
 *    2 raíces (mesial y distal) y el 1.er molar con 3 cúspides vestibulares.
 * Son PNG transparentes: solo se usa su canal alfa, que se colorea con filtros SVG.
 */
const TOOTH_SPRITES = {
  11: "data:image/png;base64,",
  12: "data:image/png;base64,",
  13: "data:image/png;base64,",
  14: "data:image/png;base64,",
  15: "data:image/png;base64,",
  16: "data:image/png;base64,",
  17: "data:image/png;base64,",
  18: "data:image/png;base64,",
  41: "data:image/png;base64,",
  42: "data:image/png;base64,",
  43: "data:image/png;base64,",
  44: "data:image/png;base64,",
  45: "data:image/png;base64,",
  46: "data:image/png;base64,",
  47: "data:image/png;base64,",
  48: "data:image/png;base64,",
};

// Conductos de cada raíz (coordenadas del dibujo de la pieza, antes del espejo y del volteo).
// La endodoncia se dibuja en todos los conductos y el poste en la raíz principal, hasta la mitad.
const CONDUCTOS = {
  11: { conductos: ["M24.0 31.0 L24.2 57.8 L24.4 77.0"], poste: "M24.0 31.0 L24.2 57.8" },
  12: { conductos: ["M24.0 31.0 L23.3 57.8 L22.7 77.0"], poste: "M24.0 31.0 L23.3 57.8" },
  13: { conductos: ["M24.0 32.0 L23.6 65.5 L23.2 91.4"], poste: "M24.0 32.0 L23.6 65.5" },
  14: { conductos: ["M24.0 30.0 L24.0 56.8 L27.0 64.8 L28.4 80.1", "M24.0 30.0 L24.0 56.8 L21.0 64.8 L19.7 78.6"], poste: "M24.0 30.0 L24.0 56.8 L27.0 64.8 L27.7 72.4" },
  15: { conductos: ["M24.0 30.0 L23.7 58.5 L23.4 79.3"], poste: "M24.0 30.0 L23.7 58.5" },
  16: { conductos: ["M24.0 29.0 L24.0 41.1 L32.4 49.1 L36.2 71.6", "M24.0 29.0 L24.0 41.1 L24.2 49.1 L24.6 76.1", "M24.0 29.0 L24.0 41.1 L16.0 49.1 L12.4 70.1"], poste: "M24.0 29.0 L24.0 41.1 L24.2 49.1 L24.4 62.6" },
  17: { conductos: ["M24.0 29.0 L24.0 43.7 L31.6 51.7 L33.4 70.3", "M24.0 29.0 L24.0 43.7 L23.8 51.7 L22.7 73.4", "M24.0 29.0 L24.0 43.7 L16.2 51.7 L13.7 68.8"], poste: "M24.0 29.0 L24.0 43.7 L23.8 51.7 L23.3 62.6" },
  18: { conductos: ["M24.0 29.0 L24.0 49.8 L30.6 57.8 L30.6 66.4", "M24.0 29.0 L24.0 49.8 L23.8 57.8 L23.1 68.8", "M24.0 29.0 L24.0 49.8 L17.2 57.8 L16.7 65.8"], poste: "M24.0 29.0 L24.0 49.8 L23.8 57.8 L23.4 63.3" },
  41: { conductos: ["M24.0 31.0 L24.0 56.9 L24.0 75.3"], poste: "M24.0 31.0 L24.0 56.9" },
  42: { conductos: ["M24.0 31.0 L23.8 59.5 L23.6 80.3"], poste: "M24.0 31.0 L23.8 59.5" },
  43: { conductos: ["M24.0 32.0 L23.7 63.8 L23.4 88.0"], poste: "M24.0 32.0 L23.7 63.8" },
  44: { conductos: ["M24.0 30.0 L23.7 58.5 L23.4 79.3"], poste: "M24.0 30.0 L23.7 58.5" },
  45: { conductos: ["M24.0 30.0 L23.7 59.3 L23.4 81.0"], poste: "M24.0 30.0 L23.7 59.3" },
  46: { conductos: ["M24.0 29.0 L24.0 39.7 L31.4 47.7 L33.7 77.5", "M24.0 29.0 L24.0 39.7 L16.6 47.7 L14.3 74.5"], poste: "M24.0 29.0 L24.0 39.7 L16.6 47.7 L15.4 61.1" },
  47: { conductos: ["M24.0 29.0 L24.0 43.1 L30.6 51.1 L31.5 74.8", "M24.0 29.0 L24.0 43.1 L17.4 51.1 L15.8 73.3"], poste: "M24.0 29.0 L24.0 43.1 L17.4 51.1 L16.6 62.2" },
  48: { conductos: ["M24.0 29.0 L24.0 49.1 L30.0 57.1 L28.7 69.4", "M24.0 29.0 L24.0 49.1 L18.0 57.1 L18.7 68.2"], poste: "M24.0 29.0 L24.0 49.1 L18.0 57.1 L18.4 62.6" },
};

function toothPosition(num) {
  return Math.abs(Number(num)) % 10;
}

function resolveSpriteKey(num) {
  const piece = Number(num);

  const temporaryAliases = {
    51: 11,
    52: 12,
    53: 13,
    54: 16,
    55: 17,
    61: 21,
    62: 22,
    63: 23,
    64: 26,
    65: 27,
    71: 31,
    72: 32,
    73: 33,
    74: 36,
    75: 37,
    81: 41,
    82: 42,
    83: 43,
    84: 46,
    85: 47,
  };

  return temporaryAliases[piece] || piece;
}

export default function ToothSVG({
  num,
  upper,
  tooth,
  onContextMenu,
  onClick,
  small,
  actionGroups,
  disabled = false,
}) {
  const w = small ? 34 : 44;
  const h = small ? 72 : 90;
  const marks = tooth?.marks || [];
  const position = toothPosition(num);
  const isTemporary = Number(num) >= 50;
  const isMolar = position >= 6 || (isTemporary && position >= 4);
  // El lado izquierdo del paciente (21-28 y 31-38, y los temporales por sus alias) se dibuja
  // como el lado derecho en espejo, para que ambos lados tengan la misma anatomía.
  const claveSprite = resolveSpriteKey(num);
  const cuadrante = Math.floor(claveSprite / 10);
  const espejo = cuadrante === 2 || cuadrante === 3;
  const claveDibujo = espejo ? (cuadrante === 2 ? claveSprite - 10 : claveSprite + 10) : claveSprite;
  const sprite = TOOTH_SPRITES[claveDibujo];
  const conductos = CONDUCTOS[claveDibujo];
  const transformEspejo = espejo ? "translate(48 0) scale(-1 1)" : undefined;

  const ausente = getWholeAction(marks, ["ausente"], actionGroups);
  const implante = getWholeAction(marks, ["implante"], actionGroups);
  const endodoncia = getWholeAction(marks, ["endodoncia"], actionGroups);
  const restoRadicular = getWholeAction(marks, ["resto_radicular"], actionGroups);
  const exodoncia = getWholeAction(marks, ["indicada_exodoncia"], actionGroups);
  const brackets = getWholeAction(marks, ["brackets"], actionGroups);
  const sellante = getWholeAction(marks, ["sellante"], actionGroups);
  const poste = getWholeAction(marks, ["poste"], actionGroups);
  const pilarPuente = getWholeAction(marks, ["pilar_puente"], actionGroups);
  const pontico = getWholeAction(marks, ["pontico"], actionGroups);
  const puente = pilarPuente || pontico;
  const protesisParcial = getWholeAction(marks, ["protesis_parcial"], actionGroups);
  const protesisTotal = getWholeAction(marks, ["protesis_total"], actionGroups);
  const gancho = getWholeAction(marks, ["gancho"], actionGroups);
  const removible = protesisParcial || protesisTotal;
  // Pieza artificial (póntico o diente de una prótesis): se dibuja solo la corona, sin raíz
  const artificial = Boolean(pontico || removible);

  const corona =
    getWholeAction(marks, [
      "corona_metal_porcelana",
      "corona_libre_metal",
      "corona_acero_cromado",
    ], actionGroups) || null;

  const fractureMarks = marks.filter(
    (mark) => mark.actionId === "fractura_coronal",
  );

  const baseStroke = "#49628f";
  const filterBaseId = `tooth-base-${num}`;
  const filterRootId = `tooth-root-${num}`;
  const filterCrownId = `tooth-crown-${num}`;
  const rootClipId = `tooth-root-clip-${num}`;
  const crownClipId = `tooth-crown-clip-${num}`;
  // Las imágenes tienen la corona arriba: las piezas superiores se voltean para que la raíz quede
  // hacia arriba y la corona hacia la línea media; las inferiores quedan con la raíz hacia abajo.
  const orientation = upper ? "translate(0 96) scale(1 -1)" : undefined;
  const rootColor = restoRadicular?.color || null;

  return (
    <svg
      width={w}
      height={h}
      viewBox="0 0 48 96"

      role="button"
	  tabIndex={disabled ? -1 : 0}
      aria-label={`Pieza dental ${num}`}
	  aria-disabled={disabled}
	  onContextMenu={(event) => {
		event.preventDefault();
		if (!disabled) onContextMenu?.(event, num);
	  }}
      onClick={(event) => {
        event.stopPropagation();
		if (!disabled) onClick?.(event, num);
      }}
	  onKeyDown={(event) => {
		if (!disabled && ["Enter", " "].includes(event.key)) {
		  event.preventDefault();
		  onClick?.(event, num);
		}
	  }}
	  className={`${disabled ? "cursor-not-allowed" : "cursor-pointer"} block select-none`}
      style={{ overflow: "visible" }}
    >
      <defs>
        <filter id={filterBaseId} colorInterpolationFilters="sRGB">
          <feFlood floodColor={baseStroke} result="paint" />
          <feComposite in="paint" in2="SourceAlpha" operator="in" />
        </filter>

        <filter id={filterRootId} colorInterpolationFilters="sRGB">
          <feFlood floodColor={rootColor || baseStroke} result="paint" />
          <feComposite in="paint" in2="SourceAlpha" operator="in" />
        </filter>

        <filter id={filterCrownId} colorInterpolationFilters="sRGB">
          <feFlood floodColor={corona?.color || baseStroke} result="paint" />
          <feComposite in="paint" in2="SourceAlpha" operator="in" />
        </filter>

        <clipPath id={rootClipId}>
          <rect x="0" y="35" width="48" height="61" />
        </clipPath>

        <clipPath id={crownClipId}>
          <rect x="0" y="0" width="48" height="39" />
        </clipPath>
      </defs>

      <g transform={orientation}>
        {!ausente && !implante && sprite && (
          <>
            <image
              href={sprite}
              transform={transformEspejo}
              x="1"
              y="1"
              width="46"
              height="94"
              preserveAspectRatio="xMidYMid meet"
              clipPath={artificial ? `url(#${crownClipId})` : undefined}
              filter={`url(#${filterBaseId})`}
              pointerEvents="none"
            />

            {rootColor && !artificial && (
              <image
                href={sprite}
                transform={transformEspejo}
                x="1"
                y="1"
                width="46"
                height="94"
                preserveAspectRatio="xMidYMid meet"
                clipPath={`url(#${rootClipId})`}
                filter={`url(#${filterRootId})`}
                pointerEvents="none"
              />
            )}

            {corona && (
              <>
                <path
                  d={
                    isMolar
                      ? "M7 11 Q9 5 17 5 H31 Q39 5 41 11 L40 34 Q36 39 24 39 Q12 39 8 34 Z"
                      : position === 3
                        ? "M13 28 Q13 13 24 5 Q35 13 35 28 Q34 38 24 39 Q14 38 13 28 Z"
                        : "M13 8 Q24 4 35 8 L35 29 Q34 38 24 39 Q14 38 13 29 Z"
                  }
                  fill={corona.color}
                  fillOpacity="0.1"
                  stroke={corona.color}
                  strokeWidth="1.2"
                  strokeDasharray="2.6 1.8"
                  strokeLinejoin="round"
                  pointerEvents="none"
                />
                <image
                  href={sprite}
                  transform={transformEspejo}
                  x="1"
                  y="1"
                  width="46"
                  height="94"
                  preserveAspectRatio="xMidYMid meet"
                  clipPath={`url(#${crownClipId})`}
                  filter={`url(#${filterCrownId})`}
                  pointerEvents="none"
                />
              </>
            )}
          </>
        )}

        {implante && (
          <>
            <path
              d="M14 29 Q15 19 24 16 Q33 19 34 29 L32 38 H16 Z"
              fill="#f8fafc"
              stroke={implante.color}
              strokeWidth="1.6"
              strokeLinejoin="round"
            />
            <path
              d="M18 38 L20 82 Q24 89 28 82 L30 38 Z"
              fill="none"
              stroke={implante.color}
              strokeWidth="1.8"
              strokeLinejoin="round"
            />
            {[47, 56, 65, 74].map((y) => (
              <line
                key={y}
                x1="19"
                y1={y}
                x2="29"
                y2={y}
                stroke={implante.color}
                strokeWidth="1"
              />
            ))}
          </>
        )}

        {sellante && !ausente && !implante && (
          <text
            x="24"
            y="25"
            transform={upper ? "translate(0 50) scale(1 -1)" : undefined}
            dominantBaseline="middle"
            textAnchor="middle"
            fontSize="10"
            fontWeight="800"
            fill={sellante.color}
            pointerEvents="none"
          >
            S
          </text>
        )}

        {brackets && !ausente && !implante && (
          <>
            <line
              x1="9"
              y1="28"
              x2="39"
              y2="28"
              stroke={brackets.color}
              strokeWidth="1.2"
            />
            <rect
              x="18"
              y="23"
              width="12"
              height="10"
              rx="2"
              fill="#ffffff"
              stroke={brackets.color}
              strokeWidth="1.4"
            />
            <line
              x1="24"
              y1="23"
              x2="24"
              y2="33"
              stroke={brackets.color}
              strokeWidth="1"
            />
          </>
        )}

        {/* Endodoncia: línea roja por cada conducto (los molares tienen 2 o 3). Poste: en la raíz
            principal, desde la cámara hasta la mitad de la raíz; si hay ambos, el poste va encima. */}
        {endodoncia && conductos && !ausente && !implante && !artificial && (
          <g transform={transformEspejo} pointerEvents="none">
            {conductos.conductos.map((d) => (
              <path
                key={d}
                d={d}
                fill="none"
                stroke={endodoncia.color}
                strokeWidth="3"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            ))}
          </g>
        )}

        {poste && conductos && !ausente && !implante && !artificial && (
          <path
            d={conductos.poste}
            transform={transformEspejo}
            fill="none"
            stroke={poste.color}
            strokeWidth="3.6"
            strokeLinecap="round"
            strokeLinejoin="round"
            pointerEvents="none"
          />
        )}

        {puente && !ausente && (
          <>
            {/* Barra del puente: sobresale a los lados para unirse con las piezas vecinas */}
            <line
              x1="-3"
              y1="1.5"
              x2="51"
              y2="1.5"
              stroke={puente.color}
              strokeWidth="2.4"
              pointerEvents="none"
            />
            {pilarPuente && (
              <line
                x1="24"
                y1="1.5"
                x2="24"
                y2="9"
                stroke={pilarPuente.color}
                strokeWidth="2"
                strokeLinecap="round"
                pointerEvents="none"
              />
            )}
          </>
        )}

        {/* Prótesis removible (parcial o total): doble línea que se une con las piezas vecinas */}
        {removible && !ausente && (
          <g pointerEvents="none" stroke={removible.color} strokeWidth="1.8">
            <line x1="-3" y1="1" x2="51" y2="1" />
            <line x1="-3" y1="5" x2="51" y2="5" />
          </g>
        )}

        {/* Gancho de la prótesis parcial: abraza la corona del diente de apoyo */}
        {gancho && !ausente && !implante && (
          <path
            d="M7 24 C 6 8, 42 8, 41 24"
            fill="none"
            stroke={gancho.color}
            strokeWidth="2.2"
            strokeLinecap="round"
            pointerEvents="none"
          />
        )}

        {fractureMarks.length > 0 && !ausente && !implante && (
          <path
            d="M14 11 L19 16 L16 20 L23 24 L20 29 L29 34"
            fill="none"
            stroke={STATUS_COLORS.rojo}
            strokeWidth="1.9"
            strokeLinecap="round"
            strokeLinejoin="round"
            pointerEvents="none"
          />
        )}

        {ausente && (
          <>
            <line
              x1="10"
              y1="10"
              x2="38"
              y2="86"
              stroke={ausente.color}
              strokeWidth="2.8"
              strokeLinecap="round"
            />
            <line
              x1="38"
              y1="10"
              x2="10"
              y2="86"
              stroke={ausente.color}
              strokeWidth="2.8"
              strokeLinecap="round"
            />
          </>
        )}

        {exodoncia && (
          <line
            x1="7"
            y1="7"
            x2="41"
            y2="89"
            stroke={exodoncia.color}
            strokeWidth="2.4"
            strokeLinecap="round"
            pointerEvents="none"
          />
        )}
      </g>
    </svg>
  );
}
